    ({ boundary, acceptedVia, isWithinCircularImport }) => ({
      boundary,
      acceptedVia,
      isWithinCircularImport,
      callbacks:
        this.hotModulesMap
          .get(boundary)
          ?.callbacks.filter((c) => c.deps.includes(acceptedVia)) ?? [],
    }),
  )

  for (const id of update.updateSet) {
    this.runtime.removeModuleCache(id)
  }

  for (const {
    boundary,
    acceptedVia,
    isWithinCircularImport,
    callbacks,
  } of applies) {
    let fresh: unknown
    try {
      this.runtime.initModule(acceptedVia)
      fresh = this.runtime.loadExports(acceptedVia)
    } catch (err) {
      if (isWithinCircularImport) {
        this.requestFullReload(
          `${acceptedVia} failed to apply HMR as it's within a circular import. Reloading page to reset the execution order.`,
        )
        return
      }
      throw err
    }
    try {
      this.currentFirstInvalidatedBy = firstInvalidatedBy
      for (const { deps, fn } of callbacks) {
        fn(
          deps.map((dep) =>
            dep === acceptedVia ? (fresh as any) : undefined,
          ),
        )
      }
    } finally {
      this.currentFirstInvalidatedBy = undefined
    }
    this.logger.debug(
      `hot updated: ${
        boundary === acceptedVia ? boundary : `${acceptedVia} via ${boundary}`
      }`,
    )
  }
}

export function updateModules(
  environment: DevEnvironment,
  file: string,
  modules: EnvironmentModuleNode[],
  timestamp: number,
  firstInvalidatedBy?: string,
): void {
  const { hot } = environment
  const updates: Update[] = []
  const invalidatedModules = new Set<EnvironmentModuleNode>()
  const traversedModules = new Set<EnvironmentModuleNode>()
  // Modules could be empty if a root module is invalidated via import.meta.hot.invalidate()
  let needFullReload: HasDeadEnd = modules.length === 0

  for (const mod of modules) {
    const boundaries: PropagationBoundary[] = []
    const hasDeadEnd = propagateUpdate(mod, traversedModules, boundaries)

    environment.moduleGraph.invalidateModule(
      mod,
      invalidatedModules,
      timestamp,
      true,
    )

    if (needFullReload) {
      continue
    }

    if (hasDeadEnd) {
      needFullReload = hasDeadEnd
      continue
    }

    // If import.meta.hot.invalidate was called already on that module for the same update,
    // it means any importer of that module can't hot update. We should fallback to full reload.
    if (
      firstInvalidatedBy &&
      boundaries.some(
        ({ acceptedVia }) => acceptedVia.url === firstInvalidatedBy,
      )
    ) {
      needFullReload = 'circular import invalidate'
      continue
    }

    updates.push(
      ...boundaries.map(
        ({ boundary, acceptedVia, isWithinCircularImport }) => ({
          type: `${boundary.type}-update` as const,
          timestamp,
          path: boundary.url,
          acceptedPath: acceptedVia.url,
          explicitImportRequired:
